#include <stdio.h>


int main(void)
{
    int depth = 0;
    const char *text = "(()";
    for (int i = 0; text[i]; i++) {
        depth += text[i] == '(' ? 1 : -1;
    }
    printf("%d\n", depth);
    return 0;
}

